/**
 * @file bsp_main.c
 * @brief MPC5744P BSP: init sequence, clocks, watchdog, PIT, interrupts.
 *
 * VERIFY every register value against the MPC5744P Reference Manual and
 * the MPC5744P.h shipped with your S32 Design Studio version.
 */
#include "bsp.h"
#include "bsp_internal.h"

/* Generated by the S32DS "MPC5744P" project template: sets IVPR and
 * the INTC in software vector mode. */
extern void xcptn_xmpl(void);

/* ======================================================================= */
/* Clocks                                                                  */
/* ======================================================================= */
/* MC_ME mode configuration bits */
#define ME_MC_MVRON     (1uL << 20)
#define ME_MC_FLAON_RUN (3uL << 16)
#define ME_MC_PLL1ON    (1uL << 7)
#define ME_MC_PLL0ON    (1uL << 6)
#define ME_MC_XOSCON    (1uL << 5)
#define ME_MC_IRCON     (1uL << 4)
#define ME_MC_SYS_PLL1  (4uL)

void bsp_clock_init(void)
{
    /* Clock sources: XOSC 40 MHz -> PLL0 -> PLL1 */
    MC_CGM.AC3_SC.B.SELCTL = 1u;     /* PLL0 reference = XOSC */
    MC_CGM.AC4_SC.B.SELCTL = 1u;     /* PLL1 reference = PLL0_PHI1 */

    /* PLL0: PHI = fref * MFD / (PREDIV * RFDPHI) = 40 * 8 / (1 * 2) = 160 MHz
     *       PHI1 = 40 * 8 / (1 * 8) = 40 MHz, VCO = 640 MHz        (VERIFY) */
    PLLDIG.PLL0DV.B.RFDPHI1 = 8u;
    PLLDIG.PLL0DV.B.RFDPHI  = 2u;
    PLLDIG.PLL0DV.B.PREDIV  = 1u;
    PLLDIG.PLL0DV.B.MFD     = 8u;

    /* PLL1: PHI = fref * MFD / (2 * RFDPHI) = 40 * 20 / 4 = 200 MHz      (VERIFY) */
    PLLDIG.PLL1DV.B.RFDPHI = 2u;
    PLLDIG.PLL1DV.B.MFD    = 20u;

    /* Peripheral bus = SYS/4 = 50 MHz */
    MC_CGM.SC_DC0.R = 0x80030000uL;

    /* Motor control clock group from PLL0_PHI (160 MHz):
     * DC0 = MOTC_CLK (FlexPWM, CTU, eTimer) /1 = 160 MHz
     * DC2 = ADC_CLK /2 = 80 MHz                                          (VERIFY) */
    MC_CGM.AC0_SC.B.SELCTL = 2u;
    MC_CGM.AC0_DC0.R = 0x80000000uL;
    MC_CGM.AC0_DC2.R = 0x80010000uL;

    /* All peripherals that select RUN_PC0 (reset default) run in every mode */
    MC_ME.RUN_PC[0].R = 0x000000FEuL;

    /* DRUN: IRC + XOSC + PLL0 + PLL1 on, system clock = PLL1_PHI */
    MC_ME.DRUN_MC.R = ME_MC_MVRON | ME_MC_FLAON_RUN | ME_MC_PLL1ON | ME_MC_PLL0ON
                    | ME_MC_XOSCON | ME_MC_IRCON | ME_MC_SYS_PLL1;

    /* Mode transition to DRUN (re-enter with new configuration) */
    MC_ME.MCTL.R = 0x30005AF0uL;
    MC_ME.MCTL.R = 0x3000A50FuL;
    while (MC_ME.GS.B.S_MTRANS == 1u) { }
}

/* ======================================================================= */
/* Software watchdog (SWT_0, clocked by 16 MHz IRC)                        */
/* ======================================================================= */
#define SWT_TIMEOUT_MS  50u

void bsp_wdg_init(void)
{
    SWT_0.SR.R = 0xC520u;                       /* soft unlock */
    SWT_0.SR.R = 0xD928u;
    SWT_0.CR.R = 0xFF000100uL;                  /* masters allowed, RIA, WEN = 0 */
    SWT_0.TO.R = 16000u * SWT_TIMEOUT_MS;       /* timeout in IRC cycles */
    SWT_0.CR.R = 0xFF000111uL;                  /* reset on timeout, soft lock, WEN = 1 */
}

void bsp_wdg_kick(void)
{
    SWT_0.SR.R = 0xA602u;
    SWT_0.SR.R = 0xB480u;
}

/* ======================================================================= */
/* PIT: 1 ms timer                                                         */
/* ======================================================================= */
void bsp_pit_init(void)
{
    PIT_0.MCR.B.MDIS = 0u;
    PIT_0.MCR.B.FRZ = 1u;                       /* stop in debug halt */
    PIT_0.TIMER[0].LDVAL.R = (PBRIDGE_CLK_HZ / 1000u) - 1u;
    PIT_0.TIMER[0].TFLG.R = 1u;
}

void bsp_isr_pit0_ch0(void)
{
    PIT_0.TIMER[0].TFLG.R = 1u;
    app_task_1ms();
}

/* ======================================================================= */
/* Interrupt controller                                                    */
/* ======================================================================= */
static void irq_prio(uint32_t vec, uint32_t prio)
{
    /* PRC_SELN0 (route to core 0) | priority                              (VERIFY) */
    INTC_0.PSR[vec].R = (uint16_t)(0x8000u | (prio & 0xFu));
}

void bsp_irq_init(void)
{
    irq_prio(IRQ_ADC1_EOC, IRQ_PRIO_FAST);
    irq_prio(IRQ_FLEXPWM0_FAULT, IRQ_PRIO_PWM_FAULT);
    irq_prio(IRQ_PIT0_CH0, IRQ_PRIO_1MS);
}

/* ======================================================================= */
/* Init / start                                                            */
/* ======================================================================= */
void bsp_init(void)
{
    xcptn_xmpl();          /* IVPR + INTC software vector mode (S32DS) */
    bsp_clock_init();
    bsp_gpio_init();       /* contactors / gate enable OFF first */
    bsp_wdg_init();
    bsp_pwm_init();        /* outputs masked */
    bsp_adc_init();
    bsp_ctu_init();
    bsp_rdc_init();
    bsp_can_init();
    bsp_pit_init();
    bsp_irq_init();
}

void bsp_start(void)
{
    bsp_pwm_start();                            /* PWM reload drives CTU -> ADC -> app_fast_isr */
    PIT_0.TIMER[0].TCTRL.R = 3u;                /* TIE | TEN */
    INTC_0.CPR0.R = 0u;                         /* accept all priorities */
    __asm__ volatile("wrteei 1" : : : "memory");
}
